// BASE CLASS — demonstrates ENCAPSULATION + provides base for INHERITANCE
package com.bank.oop.model;

import com.bank.oop.exception.InsufficientFundsException;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class Account {
    private static final Logger log = Logger.getLogger(Account.class.getName());

    // ═══ ENCAPSULATION: private fields — cannot be accessed directly ═══
    private final String accountId;       // final — immutable after creation
    private final String holderName;      // final — immutable
    private BigDecimal balance;           // mutable but ONLY through methods
    private final String accountType;

    public Account(String accountId, String holderName, BigDecimal balance, String accountType) {
        if (accountId == null || accountId.isBlank()) throw new IllegalArgumentException("accountId required");
        if (balance.signum() < 0) throw new IllegalArgumentException("Initial balance cannot be negative");
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.accountType = accountType;
    }

    // ═══ ENCAPSULATION: controlled access through public methods ═══
    public void deposit(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Deposit amount must be positive");
        balance = balance.add(amount);
        log.info(String.format("[%s] Deposited Rs.%s → balance Rs.%s", accountId, amount, balance));
    }

    // This method is POLYMORPHIC — child classes can OVERRIDE it
    public void withdraw(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Withdrawal amount must be positive");
        if (balance.compareTo(amount) < 0) {
            throw new InsufficientFundsException(
                "Account " + accountId + ": balance Rs." + balance + " insufficient for Rs." + amount);
        }
        balance = balance.subtract(amount);
        log.info(String.format("[%s] Withdrew Rs.%s → balance Rs.%s", accountId, amount, balance));
    }

    // POLYMORPHIC method — each account type calculates interest differently
    public BigDecimal calculateInterest() {
        return BigDecimal.ZERO;  // base: no interest. Overridden by SavingsAccount.
    }

    // POLYMORPHIC method — account type description
    public String getTypeDescription() {
        return accountType + " Account";  // overridden by children for richer description
    }

    // Getters — read access only. NO setBalance()!
    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getAccountType() { return accountType; }

    // Protected setter — only child classes can use this (for overdraft)
    protected void setBalance(BigDecimal newBalance) { this.balance = newBalance; }

    @Override
    public String toString() {
        return accountType + "[" + accountId + "] " + holderName + " Rs." + balance;
    }
}
