// ─── File: src/main/java/com/bank/oop/model/SavingsAccount.java ───
// INHERITANCE: extends Account. POLYMORPHISM: overrides calculateInterest()
package com.bank.oop.model;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class SavingsAccount extends Account {

    private final BigDecimal annualInterestRate;  // e.g., 0.04 = 4%
    private static final BigDecimal MIN_BALANCE = new BigDecimal("1000");

    public SavingsAccount(String accountId, String holderName, BigDecimal balance,
                          BigDecimal annualInterestRate) {
        super(accountId, holderName, balance, "SAVINGS");
        this.annualInterestRate = annualInterestRate;
    }

    // ═══ POLYMORPHISM: override to enforce minimum balance ═══
    @Override
    public void withdraw(BigDecimal amount) {
        BigDecimal remainingBalance = getBalance().subtract(amount);
        if (remainingBalance.compareTo(MIN_BALANCE) < 0) {
            throw new com.bank.oop.exception.InsufficientFundsException(
                "Savings account must maintain minimum balance Rs." + MIN_BALANCE
                + ". Current: Rs." + getBalance() + ", withdrawal: Rs." + amount);
        }
        super.withdraw(amount);  // delegate to parent after validation
    }

    // ═══ POLYMORPHISM: override to calculate savings interest ═══
    @Override
    public BigDecimal calculateInterest() {
        // Monthly interest = balance × (annual rate / 12)
        return getBalance().multiply(annualInterestRate)
            .divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }

    @Override
    public String getTypeDescription() {
        return "Savings Account (" + annualInterestRate.multiply(BigDecimal.valueOf(100)) + "% annual)";
    }

    public BigDecimal getAnnualInterestRate() { return annualInterestRate; }
}
