// EXTENSIBILITY: adding a new account type — ZERO changes to existing code!
package com.bank.oop.model;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class NRIAccount extends Account {

    private final String foreignCurrency;
    private final BigDecimal exchangeRate;  // 1 USD = 83.50 INR
    private final BigDecimal annualInterestRate;

    public NRIAccount(String accountId, String holderName, BigDecimal balanceINR,
                      String currency, BigDecimal exchangeRate, BigDecimal interestRate) {
        super(accountId, holderName, balanceINR, "NRI");
        this.foreignCurrency = currency;
        this.exchangeRate = exchangeRate;
        this.annualInterestRate = interestRate;
    }

    @Override
    public BigDecimal calculateInterest() {
        return getBalance().multiply(annualInterestRate)
            .divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }

    @Override
    public void withdraw(BigDecimal amountINR) {
        // NRI-specific: log foreign currency equivalent
        BigDecimal foreign = amountINR.divide(exchangeRate, 2, RoundingMode.HALF_UP);
        java.util.logging.Logger.getLogger(getClass().getName())
            .info(String.format("[NRI] Withdrawal Rs.%s = %s %s (FEMA compliant)", amountINR, foreign, foreignCurrency));
        super.withdraw(amountINR);
    }

    @Override
    public String getTypeDescription() {
        return "NRI Account (" + foreignCurrency + ", rate " + exchangeRate + ")";
    }
}
