package com.bank.oop.controller;

import com.bank.oop.dto.AccountSummary;
import com.bank.oop.service.InterestBatchService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/accounts")
@RequiredArgsConstructor
public class AccountController {

    private final InterestBatchService service;

    @PostMapping("/interest/month-end")
    public List<AccountSummary> monthEnd() {
        return service.processMonthEndInterest();
    }

    @PostMapping("/{accountId}/withdraw")
    public String withdraw(@PathVariable String accountId, @RequestParam BigDecimal amount) {
        return service.processWithdrawal(accountId, amount);
    }

    @GetMapping
    public List<String> listAll() {
        return service.getAllAccounts().stream()
            .map(a -> a.getAccountId() + " " + a.getTypeDescription() + " Rs." + a.getBalance())
            .toList();
    }
}
