// ─── File: src/test/java/com/bank/oop/model/FourPillarsTest.java ───
package com.bank.oop.model;

import com.bank.oop.exception.InsufficientFundsException;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class FourPillarsTest {

    // ═══ PILLAR 1: ENCAPSULATION — private data, controlled access ═══
    @Test
    void encapsulation_balanceCanOnlyChangeViaDeposit() {
        Account account = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("10000"), new BigDecimal("0.04"));
        // account.balance = 999999;  // COMPILE ERROR! balance is private.
        account.deposit(new BigDecimal("5000"));  // ONLY way to increase balance
        assertThat(account.getBalance()).isEqualByComparingTo("15000");
    }

    @Test
    void encapsulation_withdrawValidatesBeforeChanging() {
        Account account = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("5000"), new BigDecimal("0.04"));
        assertThatThrownBy(() -> account.withdraw(new BigDecimal("-100")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("positive");
    }

    // ═══ PILLAR 2: INHERITANCE — child inherits parent behavior ═══
    @Test
    void inheritance_savingsInheritsDeposit() {
        SavingsAccount savings = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("10000"), new BigDecimal("0.04"));
        savings.deposit(new BigDecimal("5000"));  // inherited from Account
        assertThat(savings.getBalance()).isEqualByComparingTo("15000");
    }

    @Test
    void inheritance_savingsIsAnAccount() {
        SavingsAccount savings = new SavingsAccount("SAV001", "Rajesh", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(savings).isInstanceOf(Account.class);  // SavingsAccount IS-A Account
    }

    // ═══ PILLAR 3: POLYMORPHISM — same call, different behavior ═══
    @Test
    void polymorphism_withdrawBehaviorDiffersPerType() {
        Account savings = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("5000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", "Priya", new BigDecimal("5000"), new BigDecimal("10000"));

        // Savings: withdraw Rs.4500 → balance Rs.500 < minimum Rs.1000 → FAILS!
        assertThatThrownBy(() -> savings.withdraw(new BigDecimal("4500")))
            .isInstanceOf(InsufficientFundsException.class)
            .hasMessageContaining("minimum balance");

        // Current: withdraw Rs.10000 (balance Rs.5000 + overdraft Rs.10000 = Rs.15000 effective) → OK!
        current.withdraw(new BigDecimal("10000"));
        assertThat(current.getBalance()).isEqualByComparingTo("-5000");  // negative = using overdraft!
    }

    @Test
    void polymorphism_interestCalculationDiffersPerType() {
        Account savings = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("120000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", "Priya", new BigDecimal("850000"), new BigDecimal("100000"));

        // SAME method call, DIFFERENT results:
        assertThat(savings.calculateInterest()).isEqualByComparingTo("400");  // 120000 × 4% / 12 = 400
        assertThat(current.calculateInterest()).isEqualByComparingTo("0");    // current: zero interest
    }

    // ═══ PILLAR 4: ABSTRACTION — tested via PaymentService interface concept ═══
    @Test
    void abstraction_callerDoesntKnowAccountType() {
        // The batch job works with Account (parent type) — doesn't know the actual type!
        List<Account> accounts = List.of(
            new SavingsAccount("SAV001", "Rajesh", new BigDecimal("100000"), new BigDecimal("0.04")),
            new CurrentAccount("CUR001", "Priya", new BigDecimal("500000"), new BigDecimal("50000")),
            new NRIAccount("NRI001", "Amit", new BigDecimal("2000000"), "USD", new BigDecimal("83.5"), new BigDecimal("0.035"))
        );

        // Process ALL accounts polymorphically — NO instanceof checks needed!
        BigDecimal totalInterest = accounts.stream()
            .map(Account::calculateInterest)  // polymorphic call on each
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 100000×4%/12 + 0 + 2000000×3.5%/12 = 333.33 + 0 + 5833.33 = 6166.66
        assertThat(totalInterest).isGreaterThan(BigDecimal.ZERO);
    }

    // ═══ EXTENSIBILITY: adding NRIAccount required ZERO changes to existing code ═══
    @Test
    void extensibility_newAccountTypeWorksWithExistingCode() {
        NRIAccount nri = new NRIAccount("NRI001", "Amit", new BigDecimal("1000000"),
            "USD", new BigDecimal("83.50"), new BigDecimal("0.035"));

        // All existing Account methods work:
        nri.deposit(new BigDecimal("100000"));  // inherited
        assertThat(nri.getBalance()).isEqualByComparingTo("1100000");

        // NRI-specific behavior:
        BigDecimal interest = nri.calculateInterest();  // overridden
        assertThat(interest).isGreaterThan(BigDecimal.ZERO);

        // Polymorphic: works as Account everywhere!
        Account asAccount = nri;
        asAccount.withdraw(new BigDecimal("50000"));  // calls NRIAccount.withdraw (FEMA check)
    }
}
```

