package com.bank.relationships.service;

import com.bank.relationships.model.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementService {

    // ═══ ASSOCIATION: uses ClearingHouse — doesn't own it ═══
    private final ClearingHouse clearingHouse;
    // SettlementService and ClearingHouse are ASSOCIATED
    // Spring injects ClearingHouse — independent lifecycles
    // Replace ClearingHouse implementation → SettlementService unchanged

    public Map<String, Object> demonstrateAllRelationships() {
        Map<String, Object> report = new LinkedHashMap<>();

        // ═══ 1. ASSOCIATION: SettlementService uses ClearingHouse ═══
        String clearingResult = clearingHouse.clearTrade("TRD-001");
        report.put("ASSOCIATION", "SettlementService USES ClearingHouse: " + clearingResult);

        // ═══ 2. AGGREGATION: Department HAS Traders (weak) ═══
        Trader rajesh = new Trader("T001", "Rajesh Kumar", "EQUITY");
        Trader priya = new Trader("T002", "Priya Sharma", "FOREX");
        Trader amit = new Trader("T003", "Amit Patel", "DERIVATIVES");

        TradingDepartment equityDesk = new TradingDepartment("Equity Trading Desk");
        equityDesk.addTrader(rajesh);
        equityDesk.addTrader(priya);

        // Dissolve department → traders SURVIVE!
        List<Trader> survivors = equityDesk.dissolve();
        report.put("AGGREGATION", "Department dissolved. Traders survive: " + survivors);
        // rajesh and priya still exist! They can join another department.

        TradingDepartment newDesk = new TradingDepartment("Global Trading Desk");
        newDesk.addTrader(rajesh);  // rajesh moves to new department — still alive!
        newDesk.addTrader(amit);
        report.put("AGGREGATION_AFTER", "New department: " + newDesk.getTraders());

        // ═══ 3. COMPOSITION: Trade OWNS Fees (strong) ═══
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        report.put("COMPOSITION", "Trade: " + trade.getTradeId()
            + " owns " + trade.getFees().size() + " fees: " + trade.getFees());
        report.put("COMPOSITION_TOTAL_FEES", "Total fees: Rs." + trade.getTotalFees());
        // If trade is deleted → all its fees are also deleted (lifecycle bound)
        // trade = null; → fees are garbage collected with the trade

        // ═══ 4. WHY OOP MATTERS ═══
        report.put("MODULARITY", "Each class (Trade, Fee, Trader, Department) is self-contained");
        report.put("MAINTAINABILITY", "Changing fee calculation doesn't affect Department code");
        report.put("REAL_WORLD", "Objects mirror real things: trades, fees, traders, departments");

        return report;
    }
}
