// ─── File: src/main/java/com/bank/transfer/service/TransferService.java ───
// ═══ ABSTRACTION: hides 6 internal steps behind ONE public method ═══
package com.bank.transfer.service;

import com.bank.transfer.dto.*;
import com.bank.transfer.model.SafeAccount;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class TransferService {

    // Simulated accounts
    private final Map<String, SafeAccount> accounts = new HashMap<>();

    public TransferService() {
        accounts.put("SAV2001", new SafeAccount("SAV2001", new BigDecimal("125000")));
        accounts.put("CUR3001", new SafeAccount("CUR3001", new BigDecimal("850000")));
        accounts.put("SAV2002", new SafeAccount("SAV2002", new BigDecimal("45000")));
    }

    // ═══ ABSTRACTION: ONE public method hides 6 internal steps ═══
    public TransferResult transfer(TransferRequest request) {
        log.info("Transfer: {} → {} Rs.{}", request.fromAccountId(), request.toAccountId(), request.amount());

        // Step 1: validate accounts exist (HIDDEN from caller)
        SafeAccount from = findAccount(request.fromAccountId());
        SafeAccount to = findAccount(request.toAccountId());

        // Step 2: validate amount (HIDDEN)
        validateAmount(request.amount());

        // Step 3: compliance check (HIDDEN — added later, caller unchanged!)
        checkCompliance(from, to, request.amount());

        // Step 4: debit source (ENCAPSULATION: from.withdraw validates internally)
        from.withdraw(request.amount());

        // Step 5: credit destination (ENCAPSULATION: to.deposit validates internally)
        to.deposit(request.amount());

        // Step 6: generate UTR and return result (HIDDEN)
        String utr = "UTR-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

        log.info("Transfer complete: {} → {} Rs.{} [{}]",
            request.fromAccountId(), request.toAccountId(), request.amount(), utr);

        return new TransferResult("SUCCESS", request.fromAccountId(), request.toAccountId(),
            request.amount(), utr, "Transfer completed. " + from.getAuditTrail().size() + " audit entries.");
    }

    // ═══ ABSTRACTION: private methods (hidden from caller) ═══
    private SafeAccount findAccount(String accountId) {
        SafeAccount account = accounts.get(accountId);
        if (account == null) throw new IllegalArgumentException("Account not found: " + accountId);
        return account;
    }

    private void validateAmount(BigDecimal amount) {
        if (amount.compareTo(new BigDecimal("10000000")) > 0) {
            throw new IllegalArgumentException("Transfer amount exceeds Rs.1 crore limit");
        }
    }

    private void checkCompliance(SafeAccount from, SafeAccount to, BigDecimal amount) {
        // RBI compliance: transfers > Rs.50,000 require additional logging
        if (amount.compareTo(new BigDecimal("50000")) > 0) {
            log.info("[COMPLIANCE] High-value transfer: {} → {} Rs.{}", 
                from.getAccountId(), to.getAccountId(), amount);
        }
    }

    public SafeAccount getAccount(String id) { return accounts.get(id); }
}
