            new TransferRequest("NONEXISTENT", "CUR3001", new java.math.BigDecimal("100"))))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("not found");
        // Caller doesn't know the service looked up accounts internally.
    }

    @Test
    void transfer_amountLimitAbstracted() {
        assertThatThrownBy(() -> service.transfer(
            new TransferRequest("SAV2001", "CUR3001", new java.math.BigDecimal("99999999"))))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("1 crore");
        // Caller doesn't know about the Rs.1 crore limit check.
    }

    @Test
    void transfer_balancesUpdatedCorrectly() {
        service.transfer(new TransferRequest("SAV2001", "CUR3001", new java.math.BigDecimal("25000")));

        assertThat(service.getAccount("SAV2001").getBalance()).isEqualByComparingTo("100000");  // 125000 - 25000
        assertThat(service.getAccount("CUR3001").getBalance()).isEqualByComparingTo("875000");  // 850000 + 25000
        // ENCAPSULATION (inside withdraw/deposit) + ABSTRACTION (transfer method) = correct result
    }
