// ─── File: src/test/java/com/bank/dispatch/OverridingTest.java ───
// PROOF: overriding is resolved at RUNTIME
package com.bank.dispatch;

import com.bank.dispatch.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class OverridingTest {

    @Test
    void runtimeProof_sameCallDifferentBehavior() {
        // Variable type: Account. Actual type: SavingsAccount / CurrentAccount.
        Account savings = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", new BigDecimal("500000"));

        // SAME method call on SAME variable type (Account):
        BigDecimal savingsInterest = savings.calculateInterest();
        BigDecimal currentInterest = current.calculateInterest();

        // DIFFERENT results — JVM dispatched to DIFFERENT methods at RUNTIME:
        assertThat(savingsInterest).isEqualByComparingTo("400");  // 120000 × 4% / 12
        assertThat(currentInterest).isEqualByComparingTo("0");    // zero for current

        // PROOF: the COMPILER didn't decide this. The JVM did.
        // The compiler saw: Account.calculateInterest() for BOTH calls.
        // At runtime: JVM checked actual type → dispatched to correct override.
    }

    @Test
    void runtimeProof_polymorphicLoop() {
        List<Account> accounts = List.of(
            new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04")),
            new CurrentAccount("CUR001", new BigDecimal("500000")),
            new SavingsAccount("SAV002", new BigDecimal("60000"), new BigDecimal("0.035"))
        );

        // ONE loop. SAME call. DIFFERENT results.
        BigDecimal totalInterest = accounts.stream()
            .map(Account::calculateInterest)  // runtime dispatch per element!
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 400 + 0 + 175 = 575
        assertThat(totalInterest).isEqualByComparingTo("575");
    }

    @Test
    void runtimeProof_objectReferenceDispatch() {
        // ULTIMATE proof: call through Object reference
        Object ref = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));

        // ref.calculateInterest();  // WON'T COMPILE — Object doesn't have calculateInterest()
        // BUT toString() IS on Object — and SavingsAccount inherits from Account which inherits from Object

        String str = ref.toString();
        // If SavingsAccount overrides toString(): JVM calls SavingsAccount.toString() at RUNTIME
        // If not: JVM calls Object.toString() → "SavingsAccount@1a2b3c"
        // This proves: JVM dispatches based on ACTUAL type, not variable type.
        assertThat(str).isNotNull();
    }

    @Test
    void overrideAnnotationCatchesMistakes() {
        // @Override makes the compiler verify the method ACTUALLY overrides something.
        // Without @Override: a typo in the method name creates a NEW method, not an override!
        // Example: calculateIntrest() instead of calculateInterest() — no error without @Override!
        // With @Override: compiler says "calculateIntrest() does not override anything" → caught!
        assertThat(true).isTrue();
    }

    @Test
    void getTypeLabelOverriddenPerType() {
        Account savings = new SavingsAccount("SAV001", BigDecimal.ZERO, new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", BigDecimal.ZERO);

        assertThat(savings.getTypeLabel()).contains("SAVINGS").contains("4");
        assertThat(current.getTypeLabel()).contains("CURRENT").contains("zero");
        // Same call, different results — runtime polymorphism!
    }

    // ═══ SUMMARY: THE KEY DIFFERENCE ═══
    @Test
    void summary_overloadingVsOverriding() {
        // OVERLOADING: same object, different ARGUMENTS → compiler picks method
        // OVERRIDING: different objects, same CALL → JVM picks method at runtime

        // Overloading = COMPILE-TIME polymorphism (static dispatch)
        // Overriding = RUNTIME polymorphism (dynamic dispatch / virtual method invocation)
        assertThat(true).isTrue();
    }
}
```

sections.s2_technical:
RULE 1 — COVARIANT RETURN TYPE: the child's return type can be the same as the parent's OR a subtype. This was added in Java 5. The rule is: if parent returns `Account`, child can return `SavingsAccount` (because SavingsAccount IS-A Account).

```java
// Parent:
public class AccountFactory {
    public Account createAccount(String id) {
        return new Account(id, BigDecimal.ZERO);
    }
}

// Child with COVARIANT return:
public class SavingsAccountFactory extends AccountFactory {
    @Override
    public SavingsAccount createAccount(String id) {
        // Return type: SavingsAccount (subtype of Account) ✅ COVARIANT
        return new SavingsAccount(id, BigDecimal.ZERO, new BigDecimal("0.04"));
    }
}

// WHY this is useful:
SavingsAccountFactory factory = new SavingsAccountFactory();
SavingsAccount sa = factory.createAccount("SAV001");  // no cast needed! Returns SavingsAccount directly.
// Without covariant return: would return Account, caller must cast: (SavingsAccount) factory.createAccount(...)

// ❌ INVALID covariant: parent returns SavingsAccount, child returns Account (WIDER, not narrower)
// class BadFactory extends SavingsAccountFactory {
//     @Override public Account createAccount(String id) { ... }  // COMPILE ERROR!
// }
```

RULE 2 — ACCESS MODIFIER: the overriding method can have the SAME or WIDER (more accessible) access, but NEVER narrower. The rule follows Liskov Substitution Principle: if a parent method is accessible, the child's version must be AT LEAST as accessible.

```java
// Parent has PROTECTED method:
public class Account {
    protected void internalProcess() {
        // accessible to subclasses and same package
    }
}

// ✅ Child WIDENS to public — more accessible:
public class SavingsAccount extends Account {
    @Override
    public void internalProcess() {
        // protected → public: WIDER access ✅
        // Anyone who could call Account.internalProcess() can still call this
    }
}

// ❌ Child NARROWS to private — COMPILE ERROR!
// public class CurrentAccount extends Account {
//     @Override
//     private void internalProcess() {
//         // protected → private: NARROWER access ❌ COMPILE ERROR!
//     }
// }

// Access modifier order (narrow → wide):
// private → default (package-private) → protected → public
// Override: can move RIGHT (widen) only. Never LEFT (narrow).
```

RULE 3 — EXCEPTION RULES: checked exceptions in the overriding method must be the SAME, a SUBTYPE (narrower), or REMOVED entirely. Cannot add NEW checked exceptions or widen to a parent exception type. Unchecked (Runtime) exceptions have NO restriction.

```java
// Parent throws IOException (checked):
public class DataLoader {
    public void loadData() throws IOException {
        // can throw IOException
    }
}

// ✅ Child throws NARROWER exception:
public class FileDataLoader extends DataLoader {
    @Override
    public void loadData() throws FileNotFoundException {
        // FileNotFoundException extends IOException — NARROWER ✅
    }
}

// ✅ Child throws NO exception:
public class CacheDataLoader extends DataLoader {
    @Override
    public void loadData() {
        // removes exception entirely ✅ — even safer for callers
    }
}

// ❌ Child throws WIDER exception — COMPILE ERROR:
// public class NetworkDataLoader extends DataLoader {
//     @Override
//     public void loadData() throws Exception {
//         // Exception is WIDER than IOException ❌ COMPILE ERROR!
//     }
// }

// ❌ Child adds NEW checked exception — COMPILE ERROR:
// public class DbDataLoader extends DataLoader {
//     @Override
//     public void loadData() throws IOException, SQLException {
//         // SQLException is NEW, not subtype of IOException ❌ COMPILE ERROR!
//     }
// }

// ✅ Unchecked exceptions: no restriction!
public class QuickLoader extends DataLoader {
    @Override
    public void loadData() throws IOException {
        throw new RuntimeException("Unchecked — always allowed!");
        // RuntimeException can be added/removed freely. No restriction.
    }
}
```

WHY these exception rules exist: Liskov Substitution Principle. Code written against the parent (`DataLoader loader = ...`) catches `IOException`. If the child throws `SQLException` (not caught), the program crashes. The child must not SURPRISE callers with exceptions they don't handle.

RULE 4 — FINAL, STATIC, PRIVATE cannot be overridden:

```java
// FINAL: sealed — cannot be overridden
public class Account {
    public final BigDecimal getAccountId() { return accountId; }
    // No child can change getAccountId() — it's SEALED.
}
// WHY: when the parent guarantees behavior that must NEVER change (security, identity).

// STATIC: not overridden — HIDDEN
public class Account {
    public static String getBankName() { return "National Bank"; }
}
public class SavingsAccount extends Account {
    public static String getBankName() { return "Savings Division"; }
    // This is METHOD HIDING, not overriding!
    // Account.getBankName() → "National Bank"
    // SavingsAccount.getBankName() → "Savings Division"
    // No polymorphism! Static methods bind at compile time to the CLASS, not the object.
}

// PRIVATE: not inherited → not overridable
public class Account {
    private void secretMethod() { }
    // Child cannot even SEE this method — cannot override it.
    // Child CAN define a method with the SAME name — but it's a NEW method, not an override.
}
```

RULE 5 — @Override annotation:

```java
// WITHOUT @Override — typo creates a NEW method silently:
public class SavingsAccount extends Account {
    public BigDecimal calculateIntrest() {  // TYPO: "Intrest" instead of "Interest"
        return getBalance().multiply(rate);
    }
    // This is a NEW method, NOT an override! Account.calculateInterest() still returns 0.
    // Bug is SILENT — no compile error, no runtime error. Just wrong behavior.
}

// WITH @Override — typo caught at compile time:
public class SavingsAccount extends Account {
    @Override
    public BigDecimal calculateIntrest() {  // COMPILE ERROR!
        // "method does not override or implement a method from a supertype"
        // Bug caught IMMEDIATELY. No silent failure.
    }
}
// ALWAYS use @Override. Non-negotiable.
```

