    @Test
    void liskov_childSubstitutableForParent() {
        Account savings = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        Account current = new CurrentAccount("CUR001", new BigDecimal("500000"));

        // Both work as Account — Liskov Substitution Principle:
        InterestResult r1 = savings.calculateInterest();
        InterestResult r2 = current.calculateInterest();
        assertThat(r1.getAmount()).isGreaterThan(BigDecimal.ZERO);
        assertThat(r2.getAmount()).isEqualByComparingTo("0");
        // Wherever Account is expected, SavingsAccount or CurrentAccount works correctly.
    }
}
