        BigDecimal fee = sa.calculateFee();  // public → public ✅
        assertThat(fee).isEqualByComparingTo("5");  // 5000 × 0.1%
    }

    // ═══ FINAL: cannot override ═══
    @Test
    void finalCannotBeOverridden() {
        Account account = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(account.getAccountId()).isEqualTo("SAV001");
        // getAccountId() is final — SavingsAccount CANNOT override it.
        // Even if SavingsAccount tried to return "FAKE", it would NOT compile.
    }

    // ═══ STATIC: hidden, NOT overridden ═══
    @Test
    void staticIsHiddenNotOverridden() {
        // Through class names — different results (hiding):
        assertThat(Account.getPolicy()).isEqualTo("Standard Banking Policy");
        assertThat(SavingsAccount.getPolicy()).isEqualTo("Savings Special Policy");

        // Through PARENT reference — proves NOT overridden:
        Account ref = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(ref.getPolicy()).isEqualTo("Standard Banking Policy");
        // ↑ If this were a true override, would return "Savings Special Policy"
        // But static binds at compile time to variable type (Account) → NOT overridden!
    }

    // ═══ PRIVATE: not inherited, not overridable ═══
    @Test
    void privateNotInherited() {
