        account.callAudit();  // calls Account.auditInternal() — private, accessible only inside Account

        SavingsAccount sa = new SavingsAccount("SAV001", BigDecimal.ZERO);
        // sa.auditInternal();  // WON'T COMPILE — private in SavingsAccount (different method!)
        // SavingsAccount has its OWN auditInternal() — NOT an override of Account's.
    }

    // ═══ LISKOV: child substitutable for parent ═══
    @Test
    void liskovSubstitution_widerAccessWorks() {
        // Code expects Account:
        Account account = new SavingsAccount("SAV001", new BigDecimal("5000"));
        account.validate();  // protected on Account → public on SavingsAccount → works!
        // If SavingsAccount had NARROWED to private: this call would fail. Liskov violated.
    }

    // ═══ COMPREHENSIVE: all modifiers in one test ═══
    @Test
    void allModifierRulesSummary() {
        // private:   NOT inherited → cannot override (child's same-name method is NEW)
        // default:   CAN override with default, protected, or public (widen)
        // protected: CAN override with protected or public (widen)
        // public:    CAN override with public ONLY (it's the widest)
        // final:     CANNOT override — sealed
        // static:    CANNOT override — hidden (compile-time binding to class)

        assertThat(true).isTrue();
    }
}
