// ─── File: src/main/java/com/bank/notify/service/NotificationDispatcher.java ───
// POLYMORPHIC DISPATCH — one method, many channel implementations
package com.bank.notify.service;

import com.bank.notify.channel.NotificationChannel;
import com.bank.notify.dto.NotificationResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
@Slf4j
public class NotificationDispatcher {

    // All channels injected by Spring (polymorphic collection!)
    private final List<NotificationChannel> channels;

    public NotificationDispatcher(List<NotificationChannel> channels) {
        this.channels = channels;
        log.info("Loaded {} notification channels: {}",
            channels.size(), channels.stream().map(NotificationChannel::getChannelName).toList());
    }

    // ═══ POLYMORPHISM: ONE method dispatches to ANY channel ═══
    public NotificationResult sendVia(String channelName, String recipient, String message) {
        NotificationChannel channel = channels.stream()
            .filter(c -> c.getChannelName().equalsIgnoreCase(channelName))
            .findFirst()
            .orElseThrow(() -> new IllegalArgumentException("Unknown channel: " + channelName));

        String result = channel.send(recipient, message);
        // JVM dispatches to the ACTUAL implementation: SmsChannel, EmailChannel, etc.
        // This code NEVER changes when a new channel is added!
        log.info("[DISPATCH] {} → {}", channelName, result);
        return new NotificationResult(channelName, recipient, result);
    }

    // ═══ POLYMORPHISM: broadcast to ALL channels ═══
    public List<NotificationResult> broadcast(String recipient, String message) {
        return channels.stream()
            .map(channel -> {
                String result = channel.send(recipient, message);  // polymorphic call per channel
                return new NotificationResult(channel.getChannelName(), recipient, result);
            })
            .toList();
    }
}
