// ─── File: src/test/java/com/bank/thissuper/ThisVsSuperTest.java ───
package com.bank.thissuper;

import com.bank.thissuper.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ThisVsSuperTest {

    // ═══ super() — calls parent constructor ═══
    @Test
    void superConstructor_initializesParentState() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("100000"), new BigDecimal("0.04"));
        // super(accountId, holderName, balance) called in constructor
        assertThat(sa.getAccountId()).isEqualTo("SAV001");     // initialized by Account's constructor
        assertThat(sa.getHolderName()).isEqualTo("Rajesh");    // initialized by Account's constructor
        assertThat(sa.getBalance()).isEqualByComparingTo("100000");
        assertThat(sa.getInterestRate()).isEqualByComparingTo("0.04");  // initialized by SavingsAccount
    }

    // ═══ this() — chains to another constructor in same class ═══
    @Test
    void thisConstructor_chainsToFullConstructor() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh");
        // this(accountId, holderName, ZERO, 0.04) called → which calls super()
        assertThat(sa.getBalance()).isEqualByComparingTo("0");
        assertThat(sa.getInterestRate()).isEqualByComparingTo("0.04");  // default rate
    }

    // ═══ super.withdraw() — calls parent's method ═══
    @Test
    void superMethod_callsParentWithdraw() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("10000"), new BigDecimal("0.04"));
        sa.withdraw(new BigDecimal("5000"));  // our check passes (10000-5000=5000 > 1000 min)
        assertThat(sa.getBalance()).isEqualByComparingTo("5000");
        // super.withdraw() did the actual debit
    }

    @Test
    void superMethod_ourCheckBeforeParent() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", new BigDecimal("5000"), new BigDecimal("0.04"));
        // Withdraw Rs.4500 → remaining Rs.500 < min Rs.1000 → OUR check fails BEFORE super.withdraw()
        assertThatThrownBy(() -> sa.withdraw(new BigDecimal("4500")))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("minimum");
        assertThat(sa.getBalance()).isEqualByComparingTo("5000");  // balance UNCHANGED — our check stopped it
    }

    // ═══ this.field vs super.field — shadowing ═══
    @Test
    void fieldShadowing_thisVsSuper() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(sa.getThisDescription()).isEqualTo("Savings Account");   // this.description
        assertThat(sa.getSuperDescription()).isEqualTo("Generic Account");  // super.description
        // Two DIFFERENT fields with the same name! this vs super resolves which one.
    }

    // ═══ this as object reference ═══
    @Test
    void thisAsReference() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", BigDecimal.ZERO, new BigDecimal("0.04"));
        assertThat(sa.getSelf()).isSameAs(sa);  // this returns the SAME object
    }

    // ═══ describe() uses both this and super ═══
    @Test
    void describeUsesBothThisAndSuper() {
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh", BigDecimal.ZERO, new BigDecimal("0.04"));
        String desc = sa.describe();
        assertThat(desc).contains("Savings Account");   // this.description
        assertThat(desc).contains("Generic Account");    // super.description
        assertThat(desc).contains("SAV001");
    }

    // ═══ Implicit super() when not written ═══
    @Test
    void implicitSuperCalledAutomatically() {
        // If constructor doesn't call this() or super(), Java inserts super() automatically.
        // Account's no-arg constructor: Account(accountId, holderName) { this(id, name, ZERO) }
        // SavingsAccount's 2-arg constructor: this(id, name, ZERO, 0.04) → eventually calls super()
        SavingsAccount sa = new SavingsAccount("SAV001", "Rajesh");
        assertThat(sa.getAccountId()).isEqualTo("SAV001");  // parent initialized via super chain
    }
}
