        // "class TradingService inherits unrelated defaults for getMarket()"
        // Three resolution strategies:
        String tradableMarket = Tradable.super.getMarket();  // "NSE"
        String auditableMarket = Auditable.super.getMarket();  // "BSE"
        return tradableMarket + " + " + auditableMarket;  // "NSE + BSE" — combined!
