    @Test
    void multipleInterfacesImplemented() {
        assertThat(service).isInstanceOf(Tradable.class);
        assertThat(service).isInstanceOf(Auditable.class);
        assertThat(service).isInstanceOf(BaseService.class);
        // Extends ONE class + implements TWO interfaces ✅
    }

