    @Test
    void conflictingDefaultResolved() {
        assertThat(service.getMarket()).isEqualTo("NSE + BSE");
        // Both interfaces had getMarket(). Class resolved the conflict.
    }

    // ═══ InterfaceName.super.method() delegates to specific interface ═══
