    void classMethodWinsOverInterfaceDefaults() {
        assertThat(service.getServiceType()).isEqualTo("BASE_SERVICE");
        // BaseService.getServiceType() wins over:
        //   Tradable.getServiceType() → "TRADING" (ignored!)
        //   Auditable.getServiceType() → "AUDIT" (ignored!)
        // Rule: class > interface default
    }

    // ═══ No diamond problem — class resolves everything ═══
    @Test
    void noDiamondProblem() {
        // Multiple class inheritance would create ambiguity (diamond problem).
        // Multiple interface implementation: class resolves conflicts explicitly.
        // No ambiguity. No silent wrong behavior. Compiler forces resolution.
        service.executeTrade("RELIANCE", 100);  // from Tradable
        String report = service.generateAuditReport();  // from Auditable
        assertThat(report).contains("Trading Service").contains("NSE + BSE");
