        record NonSerializable(String data) {}

        assertThatThrownBy(() -> {
            new ObjectOutputStream(new ByteArrayOutputStream())
                .writeObject(new NonSerializable("test"));
        }).isInstanceOf(NotSerializableException.class);
        // Without Serializable marker → NotSerializableException!
    }

    // ═══ CLONEABLE: clone() works ═══
    @Test
    void cloneable_cloneCreatesShallowCopy() {
        Trade original = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        Trade cloned = original.clone();

        assertThat(cloned.getTradeId()).isEqualTo(original.getTradeId());
        assertThat(cloned).isNotSameAs(original);  // different object!
