    @Test
    void encapsulation_immutableFields() {
        TradeConfirmation tc = new TradeConfirmation("TRD-001", "RELIANCE",
            new BigDecimal("245050"), "SETTLED", LocalDateTime.now());
        // tc.tradeId = "HACKED";  → COMPILE ERROR! private final field.
        // No setTradeId() method. Immutable. True encapsulation.
        assertThat(tc.tradeId()).isEqualTo("TRD-001");
    }

    // ═══ VALUE SEMANTICS: equals based on ALL components ═══
    @Test
    void valueSemantic_equalsOnAllComponents() {
        LocalDateTime now = LocalDateTime.of(2024, 1, 15, 10, 30);
        TradeConfirmation t1 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t2 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t3 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("999999"), "SETTLED", now);

        assertThat(t1).isEqualTo(t2);      // same data → equal!
        assertThat(t1).isNotEqualTo(t3);    // different amount → NOT equal!
        // Auto-generated equals includes ALL components. No missing field bugs!
    }

    // ═══ HASHCODE: works correctly in HashSet ═══
    @Test
    void hashCode_worksInCollections() {
        LocalDateTime now = LocalDateTime.of(2024, 1, 15, 10, 30);
        TradeConfirmation t1 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t2 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);

        Set<TradeConfirmation> set = new HashSet<>();
        set.add(t1);
        set.add(t2);  // duplicate — same data
        assertThat(set).hasSize(1);  // correctly deduplicated!
    }

