        assertThatThrownBy(() -> new TradeConfirmation(null, "X", BigDecimal.ONE, "OK", LocalDateTime.now()))
            .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("tradeId");

        assertThatThrownBy(() -> new TradeConfirmation("T1", "X", new BigDecimal("-1"), "OK", LocalDateTime.now()))
            .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("positive");
