package com.bank.sealed.service;

import com.bank.sealed.channel.*;
import com.bank.sealed.result.TransactionResult;
import java.math.BigDecimal;

public class PaymentRouter {

    // ═══ EXHAUSTIVE SWITCH — no default needed! ═══
    public String describeChannel(PaymentChannel channel) {
        return switch (channel) {
            case NeftChannel n -> "NEFT: " + n.getChannelName() + " max Rs." + n.getMaxLimit();
            case UpiChannel u -> "UPI: " + u.getChannelName() + " max Rs." + u.getMaxLimit();
            case RtgsChannel r -> "RTGS: " + r.getChannelName() + " max Rs." + r.getMaxLimit();
            // NO default! Compiler KNOWS these are the ONLY 3 types.
            // Adding ImpsChannel to permits → COMPILE ERROR HERE until handled.
        };
    }

    // ═══ Route payment to correct channel ═══
    public TransactionResult route(PaymentChannel channel, String from, String to, BigDecimal amount) {
        if (amount.compareTo(channel.getMaxLimit()) > 0) {
            return new TransactionResult.Failure("LIMIT_EXCEEDED",
                amount + " exceeds " + channel.getChannelName() + " limit " + channel.getMaxLimit());
        }
        String result = channel.transfer(from, to, amount);
        return new TransactionResult.Success("UTR-" + System.nanoTime(), amount);
    }

    // ═══ EXHAUSTIVE result handling ═══
    public String handleResult(TransactionResult result) {
        return switch (result) {
            case TransactionResult.Success s -> "✅ UTR: " + s.utr() + " Rs." + s.amount();
            case TransactionResult.Failure f -> "❌ " + f.errorCode() + ": " + f.message();
            case TransactionResult.Pending p -> "⏳ Ref: " + p.referenceId();
            // NO default! Compiler guarantees all 3 record types handled.
        };
    }
}
