    // ═══ finalize() — deprecated ═══
    @Test
    void finalize_isDeprecated() throws NoSuchMethodException {
        var method = Object.class.getDeclaredMethod("finalize");
        assertThat(method.isAnnotationPresent(Deprecated.class)).isTrue();
