// 3. NEED TO OVERRIDE MULTIPLE METHODS or add state:
Comparator<Trade> withLogging = new Comparator<Trade>() {
    private int compareCount = 0;  // STATE in anonymous class!
    @Override public int compare(Trade a, Trade b) {
        compareCount++;
        return a.getAmount().compareTo(b.getAmount());
    }
};
