class DecisionGuideTest {

    // Concrete subclass for testing:
    static class SavingsAccount extends Account {
        SavingsAccount(String id, BigDecimal bal) { super(id, bal); }
        @Override public BigDecimal calculateInterest() {
            return getBalance().multiply(new BigDecimal("0.04"));
        }
        @Override public String getType() { return "SAVINGS"; }
        @Override public BigDecimal calculateTax() {
            return calculateInterest().multiply(new BigDecimal("0.30"));
        }
    }

    @Test
    void abstractClass_hasStateAndConstructor() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("100000"));
        assertThat(sa.getAccountId()).isEqualTo("SAV001");   // field initialized by constructor
        assertThat(sa.getBalance()).isEqualByComparingTo("100000");
        // Interface CANNOT do this — no constructor, no instance fields.
    }

    @Test
    void abstractClass_implementsMultipleInterfaces() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("100000"));
        assertThat(sa).isInstanceOf(Auditable.class);  // ✅ IS Auditable
        assertThat(sa).isInstanceOf(Taxable.class);    // ✅ IS Taxable
        assertThat(sa).isInstanceOf(Account.class);    // ✅ IS Account
        // Extends ONE abstract class + implements TWO interfaces.
    }

    @Test
    void interface_providesDefaultMethods() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("100000"));
        assertThat(sa.auditSummary()).contains("Audit:");      // default from Auditable
        assertThat(sa.getTaxBracket()).isEqualTo("STANDARD");  // default from Taxable
        // Default methods add behavior WITHOUT state — the Java 8 improvement.
    }

    @Test
    void decisionFlowchart() {
        // Need balance field (mutable state)? → abstract class Account
        // Need constructor to init accountId? → abstract class Account
        // Need Auditable capability on unrelated classes? → interface Auditable
        // Need Taxable capability? → interface Taxable
        // Account extends abstract + implements both → best of both worlds!
        assertThat(true).isTrue();
    }

    @Test
    void java8DefaultsStillNotInterchangeable() {
        // Java 8 gave interfaces default methods — but STILL can't:
        // 1. Have instance fields (balance, accountId)
        // 2. Have constructors (initialize state)
        // 3. Have protected methods (access control within family)
        // Abstract classes: all of the above ✅
        // THAT'S why they're not interchangeable even after Java 8.
        assertThat(true).isTrue();
    }
}
