package com.bank.delegation.delegate;

import java.math.BigDecimal;

public class AccountOperations {
    private BigDecimal balance;

    public AccountOperations(BigDecimal initialBalance) { this.balance = initialBalance; }

    public void deposit(BigDecimal amount) { balance = balance.add(amount); }
    public void withdraw(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient");
        balance = balance.subtract(amount);
    }
    public BigDecimal getBalance() { return balance; }
    public void transferInternational(String country, BigDecimal amount) {
        withdraw(amount);  // dangerous for savings accounts!
    }
    public void closeAccount() { balance = BigDecimal.ZERO; }
}
